namespace noctrl {
class LiveModRangePanel:public juce::Component {
 SynthProcessor& p;int source;juce::String target;juce::Label title,hint;juce::Slider start,end;juce::TextButton remove{"UNLINK"};
public:
 LiveModRangePanel(SynthProcessor& processor,int s,juce::String id):p(processor),source(s),target(id){using namespace juce;setSize(330,160);for(auto* item:std::array<Component*,5>{&title,&hint,&start,&end,&remove})addAndMakeVisible(item);auto routes=p.liveMods();auto* link=routes->find(source,target);if(!link)return;title.setText(liveSourceName(source)+" > "+link->parameter->getName(55),dontSendNotification);title.setColour(Label::textColourId,liveSourceColour(source));title.setFont(FontOptions(nd::number("fontSize",12),Font::bold));title.setBounds(8,5,314,26);float delta=link->parameter->getValue()-link->base;for(auto* slider:{&start,&end}){slider->setRange(0,1,.0001);slider->setSliderStyle(Slider::LinearHorizontal);slider->setTextBoxStyle(Slider::TextBoxRight,false,80,24);slider->textFromValueFunction=[](double n){return String(n*100,1)+" %";};slider->valueFromTextFunction=[](const String& text){return text.getDoubleValue()/100;};slider->setColour(Slider::thumbColourId,liveSourceColour(source));slider->setColour(Slider::trackColourId,liveSourceColour(source));}start.setBounds(8,38,314,28);end.setBounds(8,75,314,28);start.setValue(jlimit(0.f,1.f,link->start+delta),dontSendNotification);end.setValue(jlimit(0.f,1.f,link->end+delta),dontSendNotification);start.onValueChange=end.onValueChange=[this]{auto routes=p.liveMods();if(auto* link=routes->find(source,target)){float shift=link->parameter->getValue()-link->base;p.setLiveModRange(source,target,(float)start.getValue()-shift,(float)end.getValue()-shift);}};hint.setText("Start / End. Reversed ranges are supported.",dontSendNotification);hint.setFont(FontOptions(nd::number("fontSize",10)));hint.setBounds(8,110,220,34);remove.setBounds(235,117,86,27);remove.onClick=[this]{p.removeLiveMod(source,target);if(auto* box=findParentComponentOfClass<CallOutBox>())box->dismiss();};}
 void paint(juce::Graphics& g)override{nd::Scope suitScope("controls");g.fillAll(nd::colour(juce::Colour(0xff1e2b36)));}
};
class LiveSourceHandle:public juce::Component,public juce::SettableTooltipClient {
 SynthProcessor& p;int source;bool dragging=false;
public:
 std::function<void()> onSelect;
 LiveSourceHandle(SynthProcessor& processor,int index):p(processor),source(index){setComponentID("live-source:"+juce::String(index));setTooltip(liveSourceName(source)+": drag this ring onto a knob. Click then Shift-click a knob also assigns it. Right-click to remove your links.");setMouseCursor(juce::MouseCursor::DraggingHandCursor);}
 int linkCount()const{std::set<juce::String> targets;for(auto& link:p.liveMods()->links)if(link.source==source)targets.insert(link.target);int importedSource=source==11?1:source==12?49:source+3;auto assets=std::atomic_load(&p.importedAssets);if(assets&&assets->expansion){for(auto& link:assets->expansion->mods)if(link.source==importedSource)targets.insert("import-"+juce::String(link.target));for(auto& link:assets->expansion->fxMods)if(link.source==importedSource)targets.insert("fx-"+juce::String(link.unit)+"-"+juce::String(link.target));}const int legacy[]={1,10,11,2,3,12,13,14,15,16,17,4,27};for(int i=1;i<=8;++i)if((int)p.value("mod"+juce::String(i)+"src")==legacy[source]&&p.value("mod"+juce::String(i)+"dst")>0&&std::abs(p.value("mod"+juce::String(i)+"amt"))>.00001f)targets.insert("legacy-"+juce::String((int)p.value("mod"+juce::String(i)+"dst")));return (int)targets.size();}
 juce::var dragDescription()const{auto* d=new juce::DynamicObject();d->setProperty("kind","NoCTRL.LiveMod");d->setProperty("source",source);d->setProperty("instance",juce::String::toHexString((juce::int64)(intptr_t)&p));return juce::var(d);}
 juce::Image createDragImage()const{using namespace juce;Image image(Image::ARGB,172,42,true);Graphics g(image);g.setColour(nd::colour(Colour(0xf522303d)));g.fillRoundedRectangle(image.getBounds().toFloat().reduced(1),nd::number("radius",4));g.setColour(nd::colour(liveSourceColour(source)));g.drawRoundedRectangle(image.getBounds().toFloat().reduced(1),nd::number("radius",4),1.5f);g.setFont(FontOptions(nd::number("fontSize",13),Font::bold));g.drawText(liveSourceName(source),12,4,148,18,Justification::centredLeft);g.setFont(FontOptions(nd::number("fontSize",10)));g.drawText(String(linkCount())+" destinations",12,23,148,15,Justification::centredLeft);return image;}
 void paint(juce::Graphics& g)override{nd::Scope suitScope("controls");using namespace juce;auto r=getLocalBounds().toFloat().reduced(2);float radius=jmin(r.getWidth(),r.getHeight())*.5f;auto centre=r.getCentre();g.setColour(nd::colour(nd::colour(Colour(0xff12212c))));g.fillEllipse(centre.x-radius,centre.y-radius,radius*2,radius*2);g.setColour(nd::colour(liveSourceColour(source).withAlpha(p.selectedLiveSource.load()==source?1.f:.55f)));Path arc;arc.addCentredArc(centre.x,centre.y,radius,radius,0,-2.4f,2.4f,true);g.strokePath(arc,PathStrokeType(nd::number("stroke",1.6f)));float angle=-2.4f+4.8f*p.liveSources[source].load(),x=centre.x+std::sin(angle)*radius,y=centre.y-std::cos(angle)*radius;g.setColour(nd::colour(liveSourceColour(source)));g.fillEllipse(x-1.2f,y-1.2f,2.4f,2.4f);g.setFont(FontOptions(nd::number("fontSize",8),Font::bold));g.drawText(String(linkCount()),r,Justification::centred,false);}
 void mouseDown(const juce::MouseEvent& e)override{dragging=false;if(e.mods.isPopupMenu()){juce::PopupMenu menu;menu.addSectionHeader(liveSourceName(source)+" assignments");auto routes=p.liveMods();std::vector<juce::String> targets;for(auto& link:routes->links)if(link.source==source){targets.push_back(link.target);menu.addItem((int)targets.size(),"Remove: "+link.parameter->getName(64));}if(targets.empty())menu.addItem(999,"No new assignments. Existing preset/matrix routes are retained.",false);auto safe=juce::Component::SafePointer<LiveSourceHandle>(this);menu.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(this),[safe,targets](int result){if(safe&&result>0&&result<=(int)targets.size())safe->p.removeLiveMod(safe->source,targets[(size_t)result-1]);});return;}p.selectedLiveSource.store(source);p.selectedMacro.store(-1);if(onSelect)onSelect();repaint();}
 void mouseDrag(const juce::MouseEvent& e)override{if(e.mods.isPopupMenu()||dragging||e.getDistanceFromDragStart()<4)return;if(auto* container=juce::DragAndDropContainer::findParentDragContainerFor(this)){dragging=true;auto offset=juce::Point<int>(12,10);container->startDragging(dragDescription(),this,juce::ScaledImage(createDragImage()),false,&offset,&e.source);}}
};
}
